package request

import (
	"context"
	"io"
)

type payloadKey struct{}

// Payload carries an optional streaming response beside generated byte-slice
// shapes. In-process callers retain the generated API's buffered behavior.
// The gateway owns and closes Body after encoding the generated headers.
type Payload struct {
	Body io.ReadCloser
}

func WithPayload(ctx context.Context, payload *Payload) context.Context {
	return context.WithValue(ctx, payloadKey{}, payload)
}

func ResponsePayload(ctx context.Context) *Payload {
	payload, _ := ctx.Value(payloadKey{}).(*Payload)
	return payload
}
